using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CocoonCharmOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/CocoonCharmOmenData")]
public class CocoonCharmOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.MeteorShieldOmenAction = delegate
		{
			ActivateOmen();
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.MeteorShieldOmenAction = null;
	}
}
